package com.hrcoresystem.hrcore_api.modules.tenant.employees.application.service;
import com.hrcoresystem.hrcore_api.common.exception.BusinessException; import com.hrcoresystem.hrcore_api.common.security.context.SecurityContextFacade; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import javax.sql.DataSource; import java.time.LocalDate; import java.util.UUID;
@Service public class EmployeeSupervisionScopeService { private final JdbcTemplate jdbc; private final SecurityContextFacade security; public EmployeeSupervisionScopeService(DataSource ds,SecurityContextFacade s){jdbc=new JdbcTemplate(ds);security=s;} public UUID resolveEffectiveSupervisorEmployeeId(UUID employeeId,LocalDate date){String sql="WITH RECURSIVE chain AS (SELECT ea.employee_id,ea.department_id,ea.supervisor_employee_id,0 depth FROM employee_assignments ea WHERE ea.employee_id=? AND ea.assignment_type='PRIMARY' AND ea.assignment_status='ACTIVE' AND ea.start_date<=? AND (ea.end_date IS NULL OR ea.end_date>=?) UNION ALL SELECT c.employee_id,d.parent_department_id,c.supervisor_employee_id,c.depth+1 FROM chain c JOIN departments d ON d.id=c.department_id WHERE c.depth<100), candidates AS (SELECT supervisor_employee_id supervisor_id,0 priority FROM chain WHERE supervisor_employee_id IS NOT NULL UNION ALL SELECT d.manager_employee_id,1 FROM chain c JOIN departments d ON d.id=c.department_id WHERE d.manager_employee_id IS NOT NULL) SELECT c.supervisor_id FROM candidates c JOIN employees e ON e.id=c.supervisor_id JOIN tenant_users u ON u.id=e.tenant_user_id WHERE e.employment_status='ACTIVE' AND u.active=true AND u.status='ACTIVE' ORDER BY c.priority LIMIT 1"; return jdbc.query(sql,rs->rs.next()?(UUID)rs.getObject(1):null,employeeId,date,date); } public boolean canSupervise(UUID authenticatedUserId,UUID targetEmployeeId,LocalDate date){UUID me=jdbc.query("SELECT id FROM employees e JOIN tenant_users u ON u.id=e.tenant_user_id WHERE u.id=? AND e.employment_status='ACTIVE' AND u.active=true AND u.status='ACTIVE'",rs->rs.next()?(UUID)rs.getObject(1):null,authenticatedUserId); return me!=null&&me.equals(resolveEffectiveSupervisorEmployeeId(targetEmployeeId,date));} public UUID requireCurrentEmployeeId(){UUID user=security.getCurrentUserId(); UUID employee=jdbc.query("SELECT e.id FROM employees e JOIN tenant_users u ON u.id=e.tenant_user_id WHERE u.id=? AND e.employment_status='ACTIVE' AND u.active=true AND u.status='ACTIVE'",rs->rs.next()?(UUID)rs.getObject(1):null,user); if(employee==null) throw new BusinessException("La cuenta no tiene un empleado activo asociado"); return employee;} }
